const updateTemplateStats = `-- name: UpdateTemplateStats :one
UPDATE draft_cart_templates
SET total_items = $2,
    estimated_total = $3,
    updated_at = NOW()
WHERE id = $1
RETURNING id, organization_id, customer_id, template_name, description, template_type, is_favorite, auto_reorder_enabled, reorder_frequency_days, next_reorder_date, total_items, estimated_total, metadata, notes, created_at, updated_at
`

type UpdateTemplateStatsParams struct {
	ID             uuid.UUID      `json:"id"`
	TotalItems     pgtype.Int4    `json:"total_items"`
	EstimatedTotal pgtype.Numeric `json:"estimated_total"`
}

func (q *Queries) UpdateTemplateStats(ctx context.Context, arg UpdateTemplateStatsParams) (DraftCartTemplate, error) {
	row := q.db.QueryRow(ctx, updateTemplateStats, arg.ID, arg.TotalItems, arg.EstimatedTotal)
	var i DraftCartTemplate
	err := row.Scan(
		&i.ID,
		&i.OrganizationID,
		&i.CustomerID,
		&i.TemplateName,
		&i.Description,
		&i.TemplateType,
		&i.IsFavorite,
		&i.AutoReorderEnabled,
		&i.ReorderFrequencyDays,
		&i.NextReorderDate,
		&i.TotalItems,
		&i.EstimatedTotal,
		&i.Metadata,
		&i.Notes,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
